    "code": "def concept(board):
    try:
        us = board.turn
        them = not us
        vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
        best = 0
        for m in board.legal_moves:
            if not board.is_capture(m):
                continue
            victim = board.piece_at(m.to_square)
            if victim is not None:
                vv = vals.get(victim.piece_type, 0)
            else:
                vv = 1
            attacker = board.piece_at(m.from_square)
            if attacker is None:
                continue
            av = vals.get(attacker.piece_type, 0)
            if board.is_attacked_by(them, m.to_square):
                net = vv - av
            else:
                net = vv
            if net > best:
                best = net
        return float(best)
    except Exception:
        return 0.0
